     fun stop() {
         currentJob?.cancel()
         currentJob = null
         runCatching { systemTts?.stop() }
         runCatching {
             mediaPlayer?.stop()
             mediaPlayer?.release()
         }
         mediaPlayer = null
         setSpeaking(false)
     }

