     override suspend fun <T> withScanSession(block: suspend () -> T): T {
         sessionMutex.withLock {
             activeScanSessions++
         }

         return try {
             block()
         } finally {
             sessionMutex.withLock {
                 activeScanSessions--
             }
             performDeferredCleanupIfIdle()
         }
     }

     private suspend fun scanPageWithFallback(
         chapterId: Long,
         pageIndex: Int,
         image: Bitmap,
