         /** Реплика произнесена. */
         SPOKEN,

         /** Произносить было нечего: пустой текст, ремарка без звучания. */
         SILENT,

         /** На устройстве нет TTS-движка. */
         NO_ENGINE,

         /** Движок есть, но текст принял и не озвучил. */
         REJECTED,
     }

