/**
 * Годится ли локальный движок для этого языка.
 *
 * Встроенный ML Kit содержит только латинскую модель (движок
 * `com.google.mlkit:text-recognition-latin`), поэтому для кириллицы он
 * бесполезен: на странице с русским текстом он либо молчит, либо выдаёт
 * латинский мусор, который авточтение произносит вслух. Такие страницы
 * должны идти в локальный кириллический движок.
 */
internal fun isCyrillicOcrLanguage(code: String?): Boolean = when (code?.lowercase()?.trim()) {
    "ru", "uk", "be", "bg", "sr", "mk" -> true
    else -> false
}

